package core.cache.def.impl;import java.util.*;public class SceneryDefinition{public static Map<Integer,SceneryDefinition> defs=new HashMap<>();public int id,sizeX=1,sizeY=1;public int[] childrenIds;public String name="Door";public boolean close;public static SceneryDefinition forId(int id){return defs.computeIfAbsent(id,k->{SceneryDefinition d=new SceneryDefinition();d.id=k;return d;});}public String getName(){return name;}public int getId(){return id;}public SceneryDefinition getChildObject(Object p){return this;}public int getVarbitID(){return -1;}public VarbitDefinition getConfigFile(){return null;}public int getConfigId(){return -1;}public boolean hasAction(String s){return close&&s.equalsIgnoreCase("close");}}